mapper.select:
SELECT distinct profit.crt_mon reportDate, profit.busi_date as busiDate FROM hx_profit profit
profit.acc_code='1'
AND profit.crt_mon = #{reportDate,jdbcType=VARCHAR}

SELECT profit.crt_mon, profit.busi_date, SUM(profit.lixi_inc) lixiInc, SUM(profit.lixi_pay) lixiPay, SUM(profit.invest_lixi_inc) investLixiInc, SUM(profit.invest_lixi_pay) investLixiPay, SUM(profit.fina_lixi_inc) finaLixiInc, SUM(profit.fina_lixi_pay) finaLixiPay, SUM(profit.fee_lixi_inc) feeLixiInc, SUM(profit.invest_inc) investInc, SUM(profit.change_inc) changeInc, SUM(profit.year_profit) yearProfit, SUM(profit.exch_inc) exchInc, SUM(profit.prod_pay) prodPay, SUM(profit.busi_fee) busiFee, SUM(profit.asset_imp) assetImp, SUM(profit.oper_profit) operProfit FROM hx_profit profit
AND profit.crt_mon = #{reportMon,jdbcType=VARCHAR}
AND profit.acc_code = #{flag,jdbcType=VARCHAR}
GROUP BY profit.crt_mon,profit.busi_date
